sql.where:
t.deleted = 0

    AND t.task_no LIKE CONCAT('%', #{req.taskNo}, '%')


    AND t.external_task_no LIKE CONCAT('%', #{req.externalTaskNo}, '%')


    AND t.task_type = #{req.taskType}


    AND t.work_order_id = #{req.workOrderId}


    AND t.op_task_id = #{req.opTaskId}


    AND t.carrier_no LIKE CONCAT('%', #{req.carrierNo}, '%')


    AND t.external_system_code = #{req.externalSystemCode}


    AND t.dispatch_status = #{req.dispatchStatus}


    AND t.status = #{req.status}


    AND t.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
